 String usage(){return meter.summary(I18n.text(AgentService.this,"usage_tokens"),I18n.text(AgentService.this,"remaining_tokens"));}
 void log(String s){liveText=s;RunLog.get(this).add(s);status=s+"\n"+status; if(status.length()>7000)status=status.substring(0,7000);}
 public void startGoal(String g){if(g.trim().isEmpty()||running)return;if(!ChatGptAuth.get(this).connected()){log(I18n.text(AgentService.this,"please_sign_in"));return;}if(ChatGptAuth.get(this).model().isEmpty()){log(I18n.text(AgentService.this,"load_models"));return;}GoalSettings.goal(this,g);goal=g;running=true;paused=false;limitReached=false;budget.renew();retries.reset();meter=new UsageMeter();generation++;step=0;planner=new DirectPlanner(this,meter);history=new JSONArray();LogArchive.get(this).begin(g);log(I18n.text(AgentService.this,"start_prefix")+g);observe(generation);}
 public void stopGoal(String reason){running=false;paused=false;limitReached=false;generation++;DirectPlanner old=planner;planner=null;if(old!=null)new Thread(old::cancel).start(); log(reason);}
 public void pauseGoal(String reason){if(!running)return;running=false;paused=true;generation++;DirectPlanner old=planner;planner=null;if(old!=null)new Thread(old::cancel).start();log(reason);}
 public void resumeGoal(){if(!paused)return;retries.reset();paused=false;running=true;generation++;planner=new DirectPlanner(this,meter);log(I18n.text(AgentService.this,"resume_prefix")+goal);int id=generation;handler.postDelayed(()->observe(id),500);}
 public void continueGoal(){if(!limitReached)return;limitReached=false;budget.renew();retries.reset();running=true;generation++;planner=new DirectPlanner(this,meter);log(I18n.text(AgentService.this,"continue_prefix")+goal);observe(generation);}
 void tree(AccessibilityNodeInfo n,JSONArray out,int depth)throws Exception{if(n==null||depth>18||out.length()>350)return;Rect r=new Rect();n.getBoundsInScreen(r);if(n.isVisibleToUser()){JSONObject o=new JSONObject();o.put("text",String.valueOf(n.getText()));o.put("description",String.valueOf(n.getContentDescription()));o.put("bounds",r.toShortString());o.put("editable",n.isEditable());out.put(o);}for(int i=0;i<n.getChildCount();i++)tree(n.getChild(i),out,depth+1);}
 void observe(int id){if(!running||id!=generation)return;if(floating!=null)floating.conceal();handler.postDelayed(()->capture(id),150);}
 void capture(int id){if(!running||id!=generation){if(floating!=null)floating.reveal();return;}if(budget.exhausted(GoalSettings.limit(this))){if(floating!=null)floating.reveal();stopGoal(I18n.text(AgentService.this,"limit_message",GoalSettings.limit(this)));limitReached=true;return;} takeScreenshot(Display.DEFAULT_DISPLAY,getMainExecutor(),new TakeScreenshotCallback(){public void onFailure(int code){if(floating!=null)floating.reveal();if(!running||id!=generation)return;stopGoal(I18n.text(AgentService.this,"screenshot_failed")+code);}public void onSuccess(ScreenshotResult r){if(!running||id!=generation){r.getHardwareBuffer().close();if(floating!=null)floating.reveal();return;}try{Bitmap raw=Bitmap.wrapHardwareBuffer(r.getHardwareBuffer(),r.getColorSpace());Bitmap bitmap=raw.copy(Bitmap.Config.ARGB_8888,false);r.getHardwareBuffer().close();raw.recycle();ByteArrayOutputStream bytes=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,bytes);JSONObject request=new JSONObject();request.put("goal",goal);request.put("step",step);request.put("history",history);request.put("width",bitmap.getWidth());request.put("height",bitmap.getHeight());bitmap.recycle();request.put("image",Base64.encodeToString(bytes.toByteArray(),Base64.NO_WRAP));JSONArray nodes=new JSONArray();tree(getRootInActiveWindow(),nodes,0);request.put("nodes",nodes);JSONArray apps=new JSONArray();Intent launcher=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);for(android.content.pm.ResolveInfo a:getPackageManager().queryIntentActivities(launcher,0)){JSONObject o=new JSONObject();o.put("package",a.activityInfo.packageName);o.put("label",a.loadLabel(getPackageManager()));apps.put(o);}request.put("apps",apps);budget.consume();log(I18n.text(AgentService.this,"observing_step",++step));if(floating!=null)floating.reveal();DirectPlanner current=planner;new Thread(()->send(request,id,current)).start();}catch(Exception e){if(floating!=null)floating.reveal();stopGoal(I18n.text(AgentService.this,"observe_failed")+e.getMessage());}}});}
 void send(JSONObject request,int id,DirectPlanner current){if(current==null)return;try{JSONObject action=current.next(request,(kind,text)->handler.post(()->{if(!running||generation!=id)return;if(kind.equals("summary_done")){if(!text.trim().isEmpty())log(I18n.text(AgentService.this,"thinking_prefix")+text);}else if(kind.equals("phase")){log(I18n.text(AgentService.this,text));}else if(android.os.SystemClock.uptimeMillis()-lastProgress>500){liveText=I18n.text(AgentService.this,"thinking_prefix")+text;lastProgress=android.os.SystemClock.uptimeMillis();}}));handler.post(()->{if(running&&generation==id){retries.reset();execute(action,id);}});}catch(Exception e){handler.post(()->{if(running&&generation==id)inferenceFailed(e,id);});}}
 void inferenceFailed(Exception error,int id){if(!running||generation!=id)return;String reason=I18n.text(this,"inference_failed")+ChatGptAuth.safeError(error);long delay=retries.nextDelay(error);if(delay>=0&&!budget.exhausted(GoalSettings.limit(this))){log(reason+"\n"+I18n.text(this,"retry_inference",retries.attempts(),InferenceRetry.MAX_RETRIES,(int)((delay+999)/1000)));handler.postDelayed(()->{if(running&&generation==id)observe(id);},delay);}else{pauseGoal(reason+"\n"+I18n.text(this,"error_paused"));if(floating!=null)floating.reveal();}}
 void execute(JSONObject a,int id){if(!running||id!=generation)return;if(floating!=null)floating.conceal();handler.postDelayed(()->executeNow(a,id),150);}
 void executeNow(JSONObject a,int id){if(!running||id!=generation){if(floating!=null)floating.reveal();return;}try{String type=a.getString("type");log(type+" • "+a.optString("reason"));history.put(a);switch(type){
 case "done":if(floating!=null)floating.reveal();stopGoal(I18n.text(AgentService.this,"completed_prefix")+a.optString("reason"));return;
 case "blocked":if(floating!=null)floating.reveal();stopGoal(I18n.text(AgentService.this,"blocked_prefix")+a.optString("reason"));return;
 case "tap":case "long_press":case "swipe":Path p=new Path();float x=(float)a.getDouble("x"),y=(float)a.getDouble("y");p.moveTo(x,y);if(type.equals("swipe"))p.lineTo((float)a.getDouble("x2"),(float)a.getDouble("y2"));GestureDescription g=new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,type.equals("long_press")?900:type.equals("swipe")?500:100)).build();if(!dispatchGesture(g,new GestureResultCallback(){public void onCompleted(GestureDescription d){if(floating!=null)floating.reveal();handler.postDelayed(()->observe(id),1000);}public void onCancelled(GestureDescription d){if(floating!=null)floating.reveal();if(!running||id!=generation)return;stopGoal(I18n.text(AgentService.this,"gesture_cancelled"));}},null))throw new Exception("gesture rejected");return;
 case "text":AccessibilityNodeInfo node=getRootInActiveWindow();AccessibilityNodeInfo focus=node==null?null:node.findFocus(AccessibilityNodeInfo.FOCUS_INPUT);if(focus==null||!focus.isEditable())throw new Exception(I18n.text(AgentService.this,"focus_input"));Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,a.getString("text"));if(!focus.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b))throw new Exception("text rejected");break;
 case "input_text":inputConnection().commitText(a.getString("text"),1,null);break;
 case "press_enter":android.accessibilityservice.InputMethod.AccessibilityInputConnection connection=inputConnection();long now=android.os.SystemClock.uptimeMillis();for(int action:new int[]{KeyEvent.ACTION_DOWN,KeyEvent.ACTION_UP})connection.sendKeyEvent(new KeyEvent(now,now,action,KeyEvent.KEYCODE_ENTER,0,0,KeyCharacterMap.VIRTUAL_KEYBOARD,0,KeyEvent.FLAG_SOFT_KEYBOARD));break;
 case "launch":Intent intent=getPackageManager().getLaunchIntentForPackage(a.getString("package"));if(intent==null)throw new Exception(I18n.text(AgentService.this,"app_not_found"));startActivity(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));break;
 case "back":global(GLOBAL_ACTION_BACK);break;case "home":global(GLOBAL_ACTION_HOME);break;case "recents":global(GLOBAL_ACTION_RECENTS);break;case "notifications":global(GLOBAL_ACTION_NOTIFICATIONS);break;case "quick_settings":global(GLOBAL_ACTION_QUICK_SETTINGS);break;case "wait":break;default:throw new Exception("unknown action");}if(floating!=null)floating.reveal();handler.postDelayed(()->observe(id),1200);}catch(Exception e){if(floating!=null)floating.reveal();stopGoal(I18n.text(AgentService.this,"action_failed")+e.getMessage());}}
 android.accessibilityservice.InputMethod.AccessibilityInputConnection inputConnection()throws Exception{if(Build.VERSION.SDK_INT<33)throw new Exception(I18n.text(this,"input_method_requires_13"));android.accessibilityservice.InputMethod method=getInputMethod();android.accessibilityservice.InputMethod.AccessibilityInputConnection connection=method==null?null:method.getCurrentInputConnection();if(connection==null)throw new Exception(I18n.text(this,"input_connection_missing"));return connection;}
 void global(int a)throws Exception{if(!performGlobalAction(a))throw new Exception("global action rejected");}
